chunk:
JobFinancials:
  type: object
  properties:
    contractAmount:   { type: number, description: "Total signed contract value" }
    materialCost:     { type: number }
    laborCost:        { type: number }
    overhead:         { type: number }
    margin:           { type: number }
    marginPct:        { type: number }
    amountBilled:     { type: number }
    amountPaid:       { type: number }
    currency:         { type: string, pattern: "^[A-Z]{3}$", example: "USD" }

Address:
  type: object
  properties:
    line1:      { type: string }
    line2:      { type: string }
    city:       { type: string }
    state:      { type: string }
    postalCode: { type: string }
    country:    { type: string, pattern: "^[A-Z]{2}$", example: "US" }

Timestamps:
  type: object
  properties:
    createdAt:    { type: string, format: date-time }
    updatedAt:    { type: string, format: date-time }
    contractedAt: { type: string, format: date-time }
    scheduledAt:  { type: string, format: date-time }
    completedAt:  { type: string, format: date-time }
    cancelledAt:  { type: string, format: date-time }
